function openUserPermissionsTab(slider, chatId, participant, isAdmin, options) {
	slider.createTab(AppUserPermissionsTab).open({
		participant,
		chatId,
		userId: getParticipantPeerId(participant).toUserId(),
		editingAdmin: isAdmin,
		...options
	});
}
function openCommunityUserPermissionsTab(slider, communityId, participantId, participant, onUpdated) {
	slider.createTab(AppUserPermissionsTab).open({
		communityId,
		participantId,
		participant,
		editingAdmin: true,
		onUpdated
	});
}
