			get onClose() {
				return options.onClose;
			},
			isConfirmationNeededOnClose: () => webApp.isConfirmationNeededOnClose(),
			get children() {
				return [createComponent(PopupElement.Header, {
					ref: (element) => headerEl = element,
					get children() {
						return [createComponent(PopupElement.CloseButton, {
							get canGoBack() {
								return canGoBack();
							},
							onBackClick: () => webApp.onBackClick()
						}), title];
					}
				}), createComponent(PopupElement.Body, { ref: (element) => bodyEl = element })];
			}
