function renderChatlistTopNotification(toElement, props) {
	const [title, setTitle] = createSignal(true);
	const [subtitle, setSubtitle] = createSignal(true);
	const setElement = (setter, element) => {
		setter(() => element);
	};
	const disposeRoot = render(() => createComponent(Row, {
		"class": "chatlist-top-notification",
		get clickable() {
			return props.onClick;
		},
		get contextMenu() {
			return props.contextMenu;
		},
		get children() {
			return [
				createComponent(Row.Title, { get children() {
					return title();
				} }),
				createComponent(Row.Subtitle, { get children() {
					return subtitle();
				} }),
				createComponent(Row.Icon, { icon: "next" })
			];
		}
	}), toElement);
	let disposed = false;
	const dispose = () => {
		if (disposed) return;
		disposed = true;
		disposeRoot();
	};
	return {
		setTitle: (element) => setElement(setTitle, element),
		setSubtitle: (element) => setElement(setSubtitle, element),
		dispose
	};
}
